update.foreach:
 update ord_dis_delivery_detail set other_goods_code = #{item.otherGoodsCode},distribution_amount = #{item.distributionAmount},
 distribution_quantity = #{item.distributionQuantity},distribution_package_quantity = #{item.distributionPackageQuantity},updater = #{item.updater},
update_time = #{item.updateTime} where id = #{item.id}

mapper.select:
select , case when base_goods_code is null then goods_code else concat(base_goods_code,goods_code) end as sort from ord_dis_delivery_detail where is_delete=0 and delivery_order_id=#{deliveryOrderId}
and goods_code = #{goodsCode}
and goods_name like CONCAT('%',#{goodsName},'%')
order by sort

SELECT lsi.id AS stockId, lsi.stock_code, lsi.stock_name, lsi.warehouse_id, lsi.biz_org_code FROM logc_stock_info lsi INNER JOIN logc_stock_business_switch lsbs ON lsbs.stock_code = lsi.stock_code and lsi.biz_org_code = lsbs.biz_org_code and lsbs.${isOutReturn}
lsi.is_delete = 0
and (lsi.biz_org_code = #{bizOrgCode} or lsi.id in (select stock_id from logc_stock_org_auth where biz_org_code = #{bizOrgCode}))
and lsi.is_enable = #{isEnable}

