SELECT lsi.id AS stockId, lsi.stock_code, lsi.stock_name, lsi.warehouse_id, lsi.biz_org_code FROM logc_stock_info lsi INNER JOIN logc_stock_business_switch lsbs ON lsbs.stock_code = lsi.stock_code and lsbs.biz_org_code = lsi.biz_org_code and lsbs.${isOutReturn}
lsi.is_delete = 0
and (lsi.biz_org_code = #{bizOrgCode} or lsi.id in (select stock_id from logc_stock_org_auth where biz_org_code = #{bizOrgCode}))
and lsi.is_enable = #{isEnable}
and lsi.stock_code = #{stockCode,jdbcType=VARCHAR}

select oddd.id,oddd.goods_code,oddd.line,oddd.distribution_quantity,oddd.sell_tax,oddd.vendor_code,oddd.order_quantity, oddd.carry_forward_cycle,odd.order_priority,odd.stock_code,odd.wrh_code warehouseCode,odd.biz_org_code from ord_dis_delivery_detail oddd inner join ord_dis_delivery odd on odd.id = oddd.delivery_order_id where oddd.is_delete = 0 and odd.is_delete = 0 AND odd.order_priority IS NOT NULL
and oddd.delivery_order_id in
#{id,jdbcType=BIGINT}

select t.id, t.delivery_order_id, t.goods_code, t.bar_code, t.goods_name, t.goods_image,t.line, t.order_quantity, t.arrival_quantity,
t.arrival_package_quantity, t.delivery_quantity, t.delivery_package_quantity, t.distribution_quantity, t.distribution_package_quantity,
t.distribution_specification_num, t.distribution_specification,  t.distribution_specification_unit,
t.is_gift, t.creator, t.create_time, t.line, t.base_goods_code,t.expiry
from ord_dis_delivery_detail t left join ord_dis_delivery o on o.id = t.delivery_order_id
where t.delivery_order_id = #{deliveryOrderId} and t.is_delete = 0 and o.delivery_status_code = #{deliveryStatusCode}

    and t.goods_name like CONCAT('%',#{goodsName},'%')


    and t.goods_code = #{goodsCode}


    and t.bar_code = #{barCode}

order by t.line,t.id

SELECT oddd.id, oddd.delivery_order_id, oddd.goods_code, oddd.bar_code, oddd.goods_name, oddd.goods_image, oddd.small_sort, oddd.line, oddd.org_goods_id, oddd.order_quantity, oddd.order_package_quantity, oddd.order_unit_price, oddd.order_amount, oddd.distribution_quantity, oddd.distribution_package_quantity, oddd.distribution_unit_price, oddd.distribution_amount, oddd.delivery_quantity, oddd.delivery_package_quantity, oddd.delivery_amount, oddd.arrival_quantity, oddd.arrival_package_quantity, oddd.arrival_amount, oddd.distribution_specification_num, oddd.distribution_specification, oddd.distribution_specification_unit, oddd.is_gift, oddd.goods_type, oddd.distribution_except_tax_amount, oddd.distribution_tax_amount, oddd.order_priority, oddd.wrh_price, oddd.wrh_cost_amount, oddd.wrh_except_tax_amount, oddd.wrh_tax_amount, oddd.store_stock_price, oddd.store_cost_amount, oddd.store_except_tax_amount, oddd.store_tax_amount, oddd.sell_tax, oddd.distribution_price, oddd.stockout_quantity, oddd.vendor_code, oddd.purchase_no, oddd.carry_forward_cycle, oddd.creator, oddd.create_time, oddd.updater, oddd.update_time, oddd.is_delete, oddd.base_goods_code FROM ord_dis_delivery_detail oddd INNER JOIN ord_dis_delivery odd ON oddd.delivery_order_id = odd.id AND odd.is_delete = 0 WHERE oddd.is_delete = 0 AND oddd.purchase_no IS NULL
AND odd.distribution_type = #{distributionType}
AND odd.delivery_status_code = #{deliveryStatusCode}
AND oddd.vendor_code = #{vendorCode}
AND oddd.order_priority = #{orderPriority}
AND oddd.carry_forward_cycle = #{carryForwardCycle}

SELECT SUM( arrival_quantity ) AS arrivalQuantity, SUM( arrival_amount ) AS arrivalAmount FROM ord_dis_delivery_detail oddd INNER JOIN( SELECT id FROM ord_dis_delivery odd
odd.is_delete = 0
AND odd.biz_org_code = #{bizOrgCode}
) od ON od.id = oddd.delivery_order_id

